-- AppearanceGroups.lua
-- WoW 3.3.5a (build 12340) item appearance duplicate map
-- Sources:
--   ItemDisplayInfo.dbc (client WDBC, 57986 records)
--   AzerothCore azerothcore-wotlk item_template (acore_world)
--
-- Rules:
--   Included: item class Weapon(2) or Armor(4) with InventoryType in
--     head, shoulder, shirt, chest, robe, waist, legs, feet, wrist, hands,
--     back, 1H/MH/OH weapons, 2H, shield, holdable, bow, thrown, ranged-right, tabard.
--   Excluded: neck, rings, trinkets, relics, bags, ammo, displayid 0, missing DBC displayid.
--   Appearance key = slot_category + ItemDisplayInfo visual fields
--     (ModelName[2], ModelTexture[2], GeosetGroup[3], Flags, SpellVisualID,
--      HelmetGeosetVisID[2], Texture[8], ItemVisual, ParticleColorID).
--     EXCLUDES InventoryIcon and GroupSoundIndex (icons/sounds are not appearance).
--     ItemVisual (weapon glow) COUNTS as different.
--     Paths normalized: lower-case, backslash -> slash.
--   Slot category:
--     - chest(5) and robe(20) merged
--     - one-hand weapon invtypes 13/21/22 merged (same 1H look)
--     - other InventoryTypes kept separate (2H, shield, holdable, ranged kinds, armor slots)
--     - weapon subclass is NOT part of the key (identical model = identical look)
--   Group ID = smallest displayid among items sharing the appearance key.
--   Only items whose group has 2+ members are listed (uniques omitted).
--
-- Counts: 19041 items in 5525 groups; 27046 equippable with valid display; 8005 unique-appearance items omitted; displayid_0=0, displayid_missing=0, wrong_class=15867, wrong_inv=3183.
--
-- Usage: two items are visual duplicates iff ChromieTransmog_AppearanceGroup[a] == ChromieTransmog_AppearanceGroup[b]
--        (and both are present). Missing key => unique appearance (or non-gear).
--
